import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as s,o as a,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"CodeBuddy Tutorial","description":"Install CodeBuddy IDE, the editor plugin, or the CLI from official steps and finish the first sign-in. Commands are copied from the codebuddy.cn docs, not rewritten from memory.","frontmatter":{"title":"CodeBuddy Tutorial","description":"Install CodeBuddy IDE, the editor plugin, or the CLI from official steps and finish the first sign-in. Commands are copied from the codebuddy.cn docs, not rewritten from memory.","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"products/codebuddy/codebuddy.md","filePath":"products/codebuddy/codebuddy.md","lastUpdated":1787107158000}'),n={name:"products/codebuddy/codebuddy.md"};function o(d,e,l,r,h,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="codebuddy-tutorial" tabindex="-1">CodeBuddy Tutorial <a class="header-anchor" href="#codebuddy-tutorial" aria-label="Permalink to &quot;CodeBuddy Tutorial&quot;">​</a></h1><blockquote><p>This is a <strong>tutorial</strong> — follow it once and you will download or install one surface, sign in, and send a first prompt.</p><p>Look up commands in the <a href="./codebuddy-cheatsheet.html">Cheatsheet</a>; copy recipes from the <a href="./codebuddy-cookbook.html">Cookbook</a>; untangle names in the <a href="./codebuddy-glossary.html">Glossary</a>.</p></blockquote><p>Goal: stop treating CodeBuddy as &quot;Tencent also has a coding assistant&quot; and start knowing whether to open the IDE, install the plugin, or run <code>codebuddy</code>.</p><h2 id="step-0-pick-a-surface" tabindex="-1">Step 0: pick a surface <a class="header-anchor" href="#step-0-pick-a-surface" aria-label="Permalink to &quot;Step 0: pick a surface&quot;">​</a></h2><p>The three official coding forms are not one product with three skins. The table is from the <a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">product overview</a>:</p><table tabindex="0"><thead><tr><th>Your situation</th><th>Use</th></tr></thead><tbody><tr><td>You already live in VS Code / JetBrains / Visual Studio</td><td><strong>Plugin</strong></td></tr><tr><td>You want one sentence → prototype, mock, deployable app</td><td><strong>IDE</strong></td></tr><tr><td>You work in a terminal, or need headless / CI / bulk repo edits</td><td><strong>CLI (CodeBuddy Code)</strong></td></tr></tbody></table><p>The three forms share one account quota (<a href="https://www.codebuddy.cn/docs/cli/troubleshooting" target="_blank" rel="noreferrer">troubleshooting</a>). Install one to start.</p><p>The pricing page is client-rendered. This site does not invent plan numbers. See <a href="https://www.codebuddy.cn/pricing/" target="_blank" rel="noreferrer">codebuddy.cn/pricing</a>. The page description mentions a limited-time free personal plan, a limited-time free enterprise flagship plan, and a dedicated enterprise edition.</p><h2 id="install-the-ide" tabindex="-1">Install the IDE <a class="header-anchor" href="#install-the-ide" aria-label="Permalink to &quot;Install the IDE&quot;">​</a></h2><p>Source: <a href="https://www.codebuddy.cn/docs/ide/Getting-Started/Installation" target="_blank" rel="noreferrer">Install and sign-in</a>.</p><p><strong>Requirements</strong> (official table):</p><table tabindex="0"><thead><tr><th>OS</th><th>Supported versions</th></tr></thead><tbody><tr><td>macOS</td><td>macOS 11 (Big Sur) and later</td></tr><tr><td>Windows</td><td>Windows 10 and later (Windows 7/8/8.1 not supported)</td></tr></tbody></table><p>Official note: systems that miss those versions cannot start CodeBuddy IDE.</p><p><strong>Download</strong>: <a href="https://www.codebuddy.cn/" target="_blank" rel="noreferrer">CodeBuddy CN</a> or the <a href="https://www.codebuddy.cn/ide/" target="_blank" rel="noreferrer">IDE landing page</a>, matching your CPU. Official CN download is also listed as <a href="https://copilot.tencent.com/ide" target="_blank" rel="noreferrer">copilot.tencent.com/ide</a>; intl is <a href="https://www.codebuddy.ai/" target="_blank" rel="noreferrer">codebuddy.ai</a>.</p><p><strong>macOS</strong>: drag the package into Applications.</p><p><strong>Windows</strong> (official steps):</p><ol><li>Double-click the installer. If it asks to install for the current user only, choose <strong>OK</strong>.</li><li>Accept the agreement.</li><li>Pick the install location and keep choosing <strong>Next</strong>.</li></ol><p><strong>Personal sign-in</strong> (official): open the IDE → <strong>Sign in</strong> → WeChat or phone number → return to the IDE.</p><p>Enterprise / dedicated editions use Tencent Unified Identity or an address from your admin. This tutorial does not cover purchase.</p><p>Update: top-right <strong>Account</strong> → <strong>Check for updates</strong> → <strong>Install now</strong> if a build is waiting.</p><h2 id="install-the-plugin" tabindex="-1">Install the plugin <a class="header-anchor" href="#install-the-plugin" aria-label="Permalink to &quot;Install the plugin&quot;">​</a></h2><p>Source: <a href="https://www.codebuddy.cn/docs/plugin/" target="_blank" rel="noreferrer">Plugin docs home</a>.</p><p><strong>Official minimum versions</strong> (plugin page; the overview lists Visual Studio as 17.0, the plugin page lists 17.6 — this table follows the plugin page):</p><table tabindex="0"><thead><tr><th>IDE</th><th>Minimum</th></tr></thead><tbody><tr><td>Visual Studio Code</td><td>1.82</td></tr><tr><td>Visual Studio</td><td>17.6 (VS 2022)</td></tr><tr><td>IntelliJ IDEA / PyCharm / GoLand / CLion / PhpStorm</td><td>2022.2</td></tr><tr><td>Android Studio</td><td>Flamingo | 2022.2.1</td></tr><tr><td>WeChat DevTools IDE</td><td>1.06.2409140</td></tr></tbody></table><p>Official notes: other JetBrains IDEs follow the JetBrains marketplace; a compatibility pack goes down to 2020.3 but &quot;cannot use the latest product features&quot;.</p><p><strong>VS Code</strong> (three official paths):</p><ol><li>Install VS Code 1.82+.</li><li>Install the extension by any of: <ul><li>Official one-click install (VS Code must already be installed)</li><li>Marketplace search <strong>腾讯云代码助手</strong></li><li>Download the package and install it by hand</li></ul></li></ol><p><strong>JetBrains</strong>: Settings → <strong>Plugins</strong> → search <strong>腾讯云代码助手</strong> → <strong>Install</strong>; or install from disk.</p><p><strong>Sign-in</strong>: official <a href="https://www.codebuddy.cn/docs/plugin/%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8/%E7%99%BB%E5%BD%95%E5%8F%8A%E9%80%80%E5%87%BA" target="_blank" rel="noreferrer">login page</a> — click the status-bar icon or the plugin login page.</p><p>Plugin capabilities (<a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">product overview</a>): inline completion, fix, explain, unit tests, local review, <code>@workspace</code> / <code>#Codebase</code>, chat, custom instructions, RAG knowledge bases, Hunyuan / DeepSeek model switching.</p><p>First session: open a file you know, accept one completion, then ask what the file does. For repo-level questions use the official <code>@workspace</code> or <code>#Codebase</code> mentions. Do not assume the plugin has ingested every repo at the company.</p><h2 id="install-the-cli" tabindex="-1">Install the CLI <a class="header-anchor" href="#install-the-cli" aria-label="Permalink to &quot;Install the CLI&quot;">​</a></h2><p>The product name is <strong>CodeBuddy Code</strong>. The binary is <code>codebuddy</code>. The npm package is <code>@tencent-ai/codebuddy-code</code>.</p><p>Sources: <a href="https://www.codebuddy.cn/docs/cli/installation" target="_blank" rel="noreferrer">Installation guide</a>, <a href="https://www.codebuddy.cn/docs/cli/quickstart" target="_blank" rel="noreferrer">Quick start</a>.</p><h3 id="package-managers-start-here" tabindex="-1">Package managers (start here) <a class="header-anchor" href="#package-managers-start-here" aria-label="Permalink to &quot;Package managers (start here)&quot;">​</a></h3><p><strong>Prerequisite (install page):</strong> Node.js <strong>18.20</strong> or later.</p><p>The troubleshooting page says the same. The docs overview CLI section says <code>Node.js 18.0+</code>. Tencent Cloud intl FAQ has said Node.js 22+. This page follows the install guide.</p><p>Official package-manager commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tencent-ai/codebuddy-code</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tencent-ai/codebuddy-code</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tencent-ai/codebuddy-code</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tencent-ai/codebuddy-code</span></span></code></pre></div><p><strong>Homebrew (macOS/Linux, no Node.js)</strong> from the install page:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tencent-CodeBuddy/tap</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codebuddy-code</span></span></code></pre></div><p>or:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tencent-CodeBuddy/tap/codebuddy-code</span></span></code></pre></div><p>Verify (install page):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codebuddy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h3 id="native-binary-beta" tabindex="-1">Native binary (Beta) <a class="header-anchor" href="#native-binary-beta" aria-label="Permalink to &quot;Native binary (Beta)&quot;">​</a></h3><p>The install page marks native install as <strong>Beta</strong>. Platforms: macOS (Apple Silicon or Intel x86_64), Linux (arm64 or x86_64), Windows (x86_64).</p><p>Migrate from npm:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codebuddy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>Fresh install (<strong>install page</strong>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://www.codebuddy.cn/cli/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">www.codebuddy.cn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cli</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><p>The <a href="https://www.codebuddy.cn/docs/cli/quickstart" target="_blank" rel="noreferrer">quick start</a> publishes a second official pair:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://copilot.tencent.com/cli/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">copilot.tencent.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cli</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><p>Both pages are official. Do not merge them. Follow the page you are reading.</p><p>If the command is missing, the install page says add:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.local/bin:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Windows: <code>%USERPROFILE%\\AppData\\Local\\codebuddy\\bin</code>.</p><p>Windows troubleshooting also requires <strong>Git Bash</strong> (<a href="https://www.codebuddy.cn/docs/cli/troubleshooting" target="_blank" rel="noreferrer">troubleshooting</a>).</p><p>Update:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codebuddy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>or re-run the package-manager install. Disable auto-update with <code>export DISABLE_AUTOUPDATER=1</code>.</p><p>Default config dir: <code>~/.codebuddy</code> (Windows <code>%USERPROFILE%\\.codebuddy</code>). Override with <code>CODEBUDDY_CONFIG_DIR</code>. The install page says this avoids clashes with other apps that use the CodeBuddy engine (for example WorkBuddy).</p><h2 id="sign-in-to-the-cli" tabindex="-1">Sign in to the CLI <a class="header-anchor" href="#sign-in-to-the-cli" aria-label="Permalink to &quot;Sign in to the CLI&quot;">​</a></h2><p>Source: <a href="https://www.codebuddy.cn/docs/cli/quickstart" target="_blank" rel="noreferrer">Quick start · login</a>.</p><p>On first launch:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Select login method:</span></span>
<span class="line"><span>› Log in via Chinese Site</span></span>
<span class="line"><span>  Log in via International Site</span></span>
<span class="line"><span>  Log in via Enterprise Domain</span></span>
<span class="line"><span>  Log in via iOA (Tencent only)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Method</th><th>When</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Chinese Site</strong></td><td>Users in China</td><td>Auth via copilot.tencent.com</td></tr><tr><td><strong>International Site</strong></td><td>Users outside China</td><td>Auth via codebuddy.ai</td></tr><tr><td><strong>Enterprise Domain</strong></td><td>Dedicated / private deploy</td><td>Needs the address from your company</td></tr><tr><td><strong>iOA</strong></td><td>Tencent employees</td><td>Internal only</td></tr></tbody></table><p>Use <code>↑↓</code> and <code>Enter</code>; the browser finishes auth.</p><h2 id="first-cli-session" tabindex="-1">First CLI session <a class="header-anchor" href="#first-cli-session" aria-label="Permalink to &quot;First CLI session&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/your/project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codebuddy</span></span></code></pre></div><p>Official strong recommendation:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; /init</span></span></code></pre></div><p>The <a href="https://www.codebuddy.cn/docs/cli/quickstart" target="_blank" rel="noreferrer">quick start</a> calls <code>/init</code> &quot;strongly recommended&quot;: it builds a project knowledge graph so later turns scan less. After a large structural change: <code>/clear</code> then <code>/init</code>.</p><p>Then:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; Help me analyze this project&#39;s structure</span></span></code></pre></div><p>Language: <code>/config</code> → Language after launch.</p><p>One-shot (official examples):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codebuddy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Optimize this SQL query&quot;</span></span></code></pre></div><p>When the turn needs files or shell, official docs require <code>-y</code> or <code>--dangerously-skip-permissions</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codebuddy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Review code quality of src/utils.js&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre></div><p>Permission modes: <code>Shift+Tab</code> (Windows also <code>Alt+M</code>). The quick start cycle is <code>default → bypass → accept → plan</code>. <code>--permission-mode</code> values on the <a href="https://www.codebuddy.cn/docs/cli/cli-reference" target="_blank" rel="noreferrer">CLI reference</a> are <code>default</code>, <code>acceptEdits</code>, <code>auto</code>, <code>dontAsk</code>, <code>plan</code>, <code>bypassPermissions</code>. Do not mix the short key-cycle names with the flag names in scripts.</p><p>Full command table: <a href="./codebuddy-cheatsheet.html">Cheatsheet</a>.</p><h2 id="step-4-write-down-standing-rules" tabindex="-1">Step 4: write down standing rules <a class="header-anchor" href="#step-4-write-down-standing-rules" aria-label="Permalink to &quot;Step 4: write down standing rules&quot;">​</a></h2><p>CLI troubleshooting maps <code>CLAUDE.md</code> → <code>CODEBUDDY.md</code> as the &quot;AI instructions and memory&quot; file. The user-level path in the migration sample is <code>~/.codebuddy/CODEBUDDY.md</code>. Whether a repo-root <code>CODEBUDDY.md</code> is auto-injected is not a hard sentence on that page — check <code>/config</code> and the official memory doc instead of guessing.</p><p>The official &quot;symlink (recommended)&quot; migration is in the <a href="./codebuddy-cookbook.html#migrate-from-claude-code">Cookbook</a>.</p><h2 id="guardrails" tabindex="-1">Guardrails <a class="header-anchor" href="#guardrails" aria-label="Permalink to &quot;Guardrails&quot;">​</a></h2><ul><li><strong>Copy install commands from official pages.</strong> The npm package is <code>@tencent-ai/codebuddy-code</code>, not a guessed <code>@tencent/codebuddy</code>.</li><li><strong>Native install has two official URL pairs</strong> (<code>codebuddy.cn/cli</code> and <code>copilot.tencent.com/cli</code>). Do not invent a third.</li><li><strong><code>-p</code> is not &quot;allow everything&quot;.</strong> File / shell / network turns need an explicit permission policy.</li><li><strong>Do not treat WorkBuddy, Yuanbao, or Hunyuan as the next lesson.</strong> They are one row each on the <a href="./">map</a>.</li><li><strong>Do not amplify marketing percentages</strong> such as &quot;90% efficiency&quot;.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li>Recipes: <a href="./codebuddy-cookbook.html">Cookbook</a></li><li>Commands and keys: <a href="./codebuddy-cheatsheet.html">Cheatsheet</a></li><li>Concepts: <a href="./codebuddy-glossary.html">Glossary</a></li><li>Official CLI next: the &quot;Getting started&quot; group on <a href="https://www.codebuddy.cn/docs/cli/" target="_blank" rel="noreferrer">CLI docs</a></li></ul>`,94)])])}const y=t(n,[["render",o]]);export{b as __pageData,y as default};
